object P(Vector3 p)=>new{x=p.x,y=p.y,z=p.z};
string Path(Transform t)=>t.parent?Path(t.parent)+"/"+t.name:t.name;
System.IO.Directory.CreateDirectory("Docs/BackyardReverse");EditorApplication.delayCall+=()=>{var original=UnityEngine.SceneManagement.SceneManager.GetActiveScene().path;try{var all=new List<object>();foreach(var name in new[]{"ForestLoopReverse"}){UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/"+name+".unity");Physics.SyncTransforms();var ts=UnityEngine.Object.FindObjectsByType<Transform>();var rows=ts.Where(t=>t.name.IndexOf("pool",StringComparison.OrdinalIgnoreCase)>=0||t.name.IndexOf("lake",StringComparison.OrdinalIgnoreCase)>=0||t.name=="Original house 2"||t.name=="Original house 3"||t.name.Contains("Property")).Select(t=>new{path=Path(t),p=P(t.position),scale=P(t.lossyScale),forward=P(t.forward),bounds=t.GetComponent<Renderer>()?new{min=P(t.GetComponent<Renderer>().bounds.min),max=P(t.GetComponent<Renderer>().bounds.max)}:null}).ToArray();
var near=UnityEngine.Object.FindObjectsByType<Collider>().Where(c=>Vector2.Distance(new(c.bounds.center.x,c.bounds.center.z),new(326.2f,-241.2f))<42||Vector2.Distance(new(c.bounds.center.x,c.bounds.center.z),new(370.3f,12.7f))<60).Select(c=>new{path=Path(c.transform),min=P(c.bounds.min),max=P(c.bounds.max)}).ToArray();
var text=UnityEngine.Object.FindObjectsByType<TextMesh>().Where(t=>!Racer.SceneryText.IsFloating(t)).Select(t=>new{path=Path(t.transform),text=t.text,shader=t.GetComponent<Renderer>().sharedMaterial?.shader.name,material=AssetDatabase.GetAssetPath(t.GetComponent<Renderer>().sharedMaterial)}).ToArray();
var samples=new List<object>();for(int z=-180;z<=120;z+=10)for(int x=40;x<=470;x+=10){var p=new Vector3(x,500,z);var hit=Physics.RaycastAll(p,Vector3.down,900,~0,QueryTriggerInteraction.Ignore).Where(h=>h.collider.name.StartsWith("Ground_")).OrderBy(h=>h.distance).FirstOrDefault();if(hit.collider)samples.Add(P(hit.point));}all.Add(new{scene=name,objects=rows,near,text,samples});}System.IO.File.WriteAllText("Docs/BackyardReverse/forest-baseline.json",Newtonsoft.Json.JsonConvert.SerializeObject(all,Newtonsoft.Json.Formatting.Indented));}catch(Exception e){System.IO.File.WriteAllText("Docs/BackyardReverse/audit-error.txt",e.ToString());}finally{UnityEditor.SceneManagement.EditorSceneManager.OpenScene(original);}};return "Read-only audit scheduled";

